sys_script_include.script:
/**
 * StoreAssignmentUtil
 *
 * Single source of truth:
 * Dark Store.manager -> sys_user
 *
 * Provides reusable methods for dashboards, UI Pages,
 * Business Rules, Script Includes and GlideAjax calls.
 */

var StoreAssignmentUtil = Class.create()
StoreAssignmentUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    initialize: function () {},

    /**
     * Returns the sys_id of the Dark Store assigned to the user.
     */
    getAssignedStore: function (userSysId) {
        var userId = userSysId || this.getParameter('sysparm_user_sys_id')

        if (!userId) return null

        var storeGR = new GlideRecord('x_2145749_qc_dark_store')
        storeGR.addQuery('manager', userId)
        storeGR.query()

        if (storeGR.next()) return storeGR.getUniqueValue()

        return null
    },

    /**
     * Returns the Store Manager sys_id for a Dark Store.
     */
    getStoreManager: function (storeSysId) {
        var storeId = storeSysId || this.getParameter('sysparm_store_sys_id')

        if (!storeId) return null

        var storeGR = new GlideRecord('x_2145749_qc_dark_store')

        if (storeGR.get(storeId)) return storeGR.getValue('manager')

        return null
    },

    /**
     * Returns true if the user has the dark_store_manager role.
     */
    isStoreManager: function (userSysId) {
        var userId = userSysId || this.getParameter('sysparm_user_sys_id')

        if (!userId) return false

        var roleGR = new GlideRecord('sys_user_has_role')
        roleGR.addQuery('user', userId)
        roleGR.addQuery('role.name', 'x_2145749_qc.dark_store_manager')
        roleGR.addQuery('state', 'active')
        roleGR.setLimit(1)
        roleGR.query()

        return roleGR.hasNext()
    },

    /**
     * Returns true if this manager owns a Dark Store.
     */
    hasAssignedStore: function (userSysId) {
        return this.getAssignedStore(userSysId) !== null
    },

    /**
     * Returns complete store information for dashboards.
     *
     * Returns JSON.
     */
    getStoreDetails: function (userSysId) {
        var userId = userSysId || this.getParameter('sysparm_user_sys_id') || gs.getUserID()

        var storeId = this.getAssignedStore(userId)

        if (!storeId) {
            return JSON.stringify({
                assigned: false,
                message: 'No Dark Store has been assigned to your account.',
            })
        }

        var storeGR = new GlideRecord('x_2145749_qc_dark_store')

        if (!storeGR.get(storeId)) {
            return JSON.stringify({
                assigned: false,
                message: 'Assigned Dark Store record not found.',
            })
        }

        return JSON.stringify({
            assigned: true,

            store_sys_id: storeGR.getUniqueValue(),

            store_name: storeGR.getDisplayValue('store_name'),

            store_code: storeGR.getValue('store_code'),

            city: storeGR.getValue('city'),

            zone: storeGR.getDisplayValue('zone'),

            status: storeGR.getValue('status'),

            pulse_score: storeGR.getValue('pulse_score'),

            pulse_score_band: storeGR.getValue('pulse_score_band'),

            daily_order_volume: storeGR.getValue('daily_order_volume'),

            manager_sys_id: storeGR.getValue('manager'),

            manager_name: storeGR.getDisplayValue('manager'),
        })
    },

    type: 'StoreAssignmentUtil',
})
